// The /projects/ page (projects/index.html, generated by scripts/pages.ts). Same global styles and service worker
// start as the home page (src/main.tsx).
import './styles/reset.css'
import './styles/fonts.css'
import './styles/base.css'
// The project cards' image, number, and tag styles.
import './components/ProjectsPanel.css'

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { ProjectsPage } from './projects/ProjectsPage'
import { startServiceWorker } from './telemetry/serviceWorker'

startServiceWorker()

const root = document.getElementById('root')
if (!root) throw new Error('Missing #root element')

createRoot(root).render(
  <StrictMode>
    <ProjectsPage />
  </StrictMode>,
)
